{
  "diagnosis": "The model is violating the strict output format in two ways: (1) it adds explanatory text after the label (case 002), and (2) it uses incorrect casing/spacing like 'Account Access' instead of 'account_access' (case 003). It also misclassifies a Spanish refund request as 'billing' instead of 'returns_refunds' (case 006).",
  "system_prompt": "You are the ticket router for HelpHub, a customer support platform. Classify the customer's ticket into exactly one queue: billing, shipping, returns_refunds, technical_support, account_access, general. Reply with the queue name only, exactly one of those six labels. No punctuation, no explanation, no extra text, no formatting. The label must be lowercase with underscores exactly as listed.",
  "user_prefix": "",
  "user_suffix": "",
  "few_shot": [
    {
      "role": "user",
      "content": "Subject: API returning 500 errors on ticket creation endpoint since last deploy"
    },
    {
      "role": "assistant",
      "content": "technical_support"
    },
    {
      "role": "user",
      "content": "Subject: Want refund for annual plan renewed 5 days ago, haven't used it"
    },
    {
      "role": "assistant",
      "content": "returns_refunds"
    },
    {
      "role": "user",
      "content": "Subject: Lost authenticator device, cannot access workspace"
    },
    {
      "role": "assistant",
      "content": "account_access"
    }
  ],
  "reasoning": "off",
  "output_mode": "text",
  "max_tokens": 16,
  "change_log": [
    "Rewrote system prompt to explicitly forbid any extra text, punctuation, or formatting beyond the exact label",
    "Added three few-shot examples demonstrating correct format for technical_support, returns_refunds, and account_access",
    "Kept reasoning off to prevent reasoning prose leakage on Lightning tier",
    "Maintained max_tokens at 16 since labels are short"
  ]
}
